import pandas as pd
import numpy as np

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    postings = inputs["postings"].copy()

    # Sort by account_id, post_date, post_seq to match cursor order
    postings = postings.sort_values(
        by=["account_id", "post_date", "post_seq"],
        na_position="last"
    ).reset_index(drop=True)

    posted_totals_rows = []
    reject_counts_rows = []

    prev_acct = None
    tot = 0.0
    rej = 0

    for idx, row in postings.iterrows():
        curr_acct = row["account_id"]

        # Account boundary: flush previous reject count and reset
        if curr_acct != prev_acct:
            if prev_acct is not None:
                reject_counts_rows.append({
                    "account_id": prev_acct,
                    "reject_count": rej
                })
            tot = 0.0
            rej = 0
            prev_acct = curr_acct

        # Row-level validation
        qty = row["qty"]
        unit_price = row["unit_price"]

        # Check rejection conditions
        reject = False
        if pd.isna(qty) or pd.isna(unit_price):
            reject = True
        elif qty <= 0:
            reject = True
        elif unit_price < 0:
            reject = True

        if reject:
            # Row is rejected: increment reject count, skip posting
            rej += 1
        else:
            # Row is accepted: compute value, update running total, post
            v = qty * unit_price
            tot = tot + v
            posted_totals_rows.append({
                "account_id": curr_acct,
                "post_seq": row["post_seq"],
                "post_date": row["post_date"],
                "post_value": v,
                "running_total": tot
            })

    # Flush final account's reject count
    if prev_acct is not None:
        reject_counts_rows.append({
            "account_id": prev_acct,
            "reject_count": rej
        })

    # Build output DataFrames
    if posted_totals_rows:
        posted_totals = pd.DataFrame(posted_totals_rows)
    else:
        posted_totals = pd.DataFrame(columns=[
            "account_id", "post_seq", "post_date", "post_value", "running_total"
        ])

    if reject_counts_rows:
        reject_counts = pd.DataFrame(reject_counts_rows)
    else:
        reject_counts = pd.DataFrame(columns=["account_id", "reject_count"])

    # Ensure correct dtypes
    if not posted_totals.empty:
        posted_totals["account_id"] = posted_totals["account_id"].astype("int64")
        posted_totals["post_seq"] = posted_totals["post_seq"].astype("int64")
        posted_totals["post_date"] = pd.to_datetime(posted_totals["post_date"])
        posted_totals["post_value"] = posted_totals["post_value"].astype("float64")
        posted_totals["running_total"] = posted_totals["running_total"].astype("float64")
    else:
        posted_totals["account_id"] = posted_totals["account_id"].astype("int64")
        posted_totals["post_seq"] = posted_totals["post_seq"].astype("int64")
        posted_totals["post_date"] = pd.to_datetime(posted_totals["post_date"])
        posted_totals["post_value"] = posted_totals["post_value"].astype("float64")
        posted_totals["running_total"] = posted_totals["running_total"].astype("float64")

    if not reject_counts.empty:
        reject_counts["account_id"] = reject_counts["account_id"].astype("int64")
        reject_counts["reject_count"] = reject_counts["reject_count"].astype("int64")
    else:
        reject_counts["account_id"] = reject_counts["account_id"].astype("int64")
        reject_counts["reject_count"] = reject_counts["reject_count"].astype("int64")

    return {
        "posted_totals": posted_totals,
        "reject_counts": reject_counts
    }
